import { Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { useEffect, useState, type ReactNode } from 'react'
import { Card } from '../../components/Card'
import { OperatorLayout } from '../../layouts/OperatorLayout'
import { getOperatorAnalytics, subscribeToOperatorUpdates, type OperatorAnalytics } from '../../services/operatorService'

const tooltipStyle = { background: 'var(--tp-surface)', border: '1px solid var(--tp-border)', borderRadius: 'var(--tp-button-radius)', color: 'var(--tp-text)' }
const colors = ['var(--tp-primary)', 'var(--tp-cta-strong)', 'var(--tp-success)', 'var(--tp-warning)']
function Insight({ children }: { children: ReactNode }) { return <p className="analytics-insight"><span>✦ Insight</span>{children}</p> }
export function OperatorAnalyticsPage() {
  const [data, setData] = useState<OperatorAnalytics | null>(null); const [error, setError] = useState('')
  useEffect(() => { const load = () => { void getOperatorAnalytics().then(setData).catch((reason) => setError(reason instanceof Error ? reason.message : 'Analytics data is unavailable.')) }; load(); return subscribeToOperatorUpdates(load) }, [])
  const cancellations = data?.cancellations || []; const matchTrend = data?.preferenceMatch || []; const patterns = data?.patterns || []; const disruptions = data?.disruptions || []
  return <OperatorLayout><section className="operator-page"><header className="operator-page-heading"><div><p className="eyebrow">Analytics</p><h1>Signals behind better journeys.</h1><p>See what is changing across trip quality, preferences, and operations.</p></div></header>{error && <p className="auth-error">{error}</p>}<div className="analytics-grid"><Card className="analytics-card"><h2>Most cancelled components</h2><div className="analytics-chart"><ResponsiveContainer height="100%" width="100%"><BarChart data={cancellations}><CartesianGrid stroke="var(--tp-border)" vertical={false} /><XAxis dataKey="label" tick={{ fill: 'var(--tp-text-muted)', fontSize: 11 }} tickLine={false} /><YAxis tick={{ fill: 'var(--tp-text-muted)', fontSize: 11 }} tickLine={false} /><Tooltip contentStyle={tooltipStyle} /><Bar dataKey="value" fill="var(--tp-danger)" radius={6} /></BarChart></ResponsiveContainer></div><Insight>{cancellations.reduce((sum, item) => sum + item.value, 0)} cancelled itinerary component(s) recorded.</Insight></Card><Card className="analytics-card"><h2>Preference-match trend</h2><div className="analytics-chart"><ResponsiveContainer height="100%" width="100%"><LineChart data={matchTrend}><CartesianGrid stroke="var(--tp-border)" vertical={false} /><XAxis dataKey="week" tick={{ fill: 'var(--tp-text-muted)', fontSize: 11 }} tickLine={false} /><YAxis domain={[0, 100]} tick={{ fill: 'var(--tp-text-muted)', fontSize: 11 }} tickLine={false} /><Tooltip contentStyle={tooltipStyle} /><Line dataKey="score" dot={{ fill: 'var(--tp-primary)' }} stroke="var(--tp-primary)" strokeWidth={3} type="monotone" /></LineChart></ResponsiveContainer></div><Insight>Average generated-trip match: {data?.averagePreferenceMatch || 0}%.</Insight></Card><Card className="analytics-card"><h2>Customization patterns</h2><div className="analytics-chart"><ResponsiveContainer height="100%" width="100%"><PieChart><Pie cx="50%" cy="50%" data={patterns} dataKey="value" innerRadius="52%" outerRadius="78%" paddingAngle={3}>{patterns.map((item, index) => <Cell fill={colors[index % colors.length]} key={item.name} />)}</Pie></PieChart></ResponsiveContainer></div><Insight>Includes actual edits, swaps, simulations, and recovery approvals.</Insight></Card><Card className="analytics-card"><h2>Disruption frequency by type</h2><div className="analytics-chart"><ResponsiveContainer height="100%" width="100%"><BarChart data={disruptions}><CartesianGrid stroke="var(--tp-border)" vertical={false} /><XAxis dataKey="label" tick={{ fill: 'var(--tp-text-muted)', fontSize: 11 }} tickLine={false} /><YAxis tick={{ fill: 'var(--tp-text-muted)', fontSize: 11 }} tickLine={false} /><Tooltip contentStyle={tooltipStyle} /><Bar dataKey="value" fill="var(--tp-cta-strong)" radius={6} /></BarChart></ResponsiveContainer></div><Insight>{disruptions.reduce((sum, item) => sum + item.value, 0)} recorded disruption(s) grouped by real cause.</Insight></Card></div></section></OperatorLayout>
}
